contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Record the test contract's Ether balance before any interaction.
        uint256 startBal = address(this).balance;

        // Deposit amount into c.
        c.deposit{value: amount}();
        uint256 cBalAfterDeposit = address(c).balance;

        // Refund the deposit. The rule is that this must succeed.
        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalFinal = address(c).balance;
        uint256 finalBal = address(this).balance;

        // General rule: refund succeeds, returns exactly the depositor's Ether,
        // and c keeps no balance attributable to the depositor afterward.
        // Written as non-negative, underflow-safe equations.
        assert(
            !reverted &&
            finalBal == startBal &&
            cBalFinal + amount == cBalAfterDeposit
        );
    }
    receive() external payable {}
}

